"""Render the bilingual ophthalmology desk. Run site_header.py last."""
from pathlib import Path
from html import escape as e
import json,re
ROOT=Path(__file__).resolve().parents[1]
resources=json.loads((ROOT/'assets/cabinet/resources.json').read_text())
TASKS={'ru':{'imaging':'Разобрать снимок','angle':'Посмотреть угол','guidelines':'Найти рекомендации','calculate':'Рассчитать ИОЛ','patient':'Объяснить пациенту'},'en':{'imaging':'Interpret an image','angle':'Examine the angle','guidelines':'Find guidelines','calculate':'Calculate an IOL','patient':'Explain to a patient'}}
for lang in ('ru','en'):
    ru=lang=='ru'; prefix='' if ru else '/en'; path=f'{prefix}/for-doctors/cabinet/'
    base=(ROOT/f'{prefix.lstrip("/") + "/" if prefix else ""}for-doctors/free-learning/index.html').read_text()
    title='Кабинет офтальмолога' if ru else 'Ophthalmologist’s Desk'
    desc='Рабочие ресурсы офтальмолога по задачам приёма: ОКТ, атласы, гониоскопия, рекомендации, расчёт ИОЛ и материалы для пациентов.' if ru else 'Practical ophthalmology resources by clinical task: OCT, image atlases, gonioscopy, guidelines, IOL calculation and patient information.'
    head=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>{title} — {'Матвей Шемякин' if ru else 'Matvey Shemyakin'}</title><meta name="description" content="{desc}"><meta name="theme-color" content="#06182f"><meta name="robots" content="index,follow"><link rel="canonical" href="https://matveyshemyakin.ru{path}"><link rel="alternate" hreflang="ru" href="https://matveyshemyakin.ru/for-doctors/cabinet/"><link rel="alternate" hreflang="en" href="https://matveyshemyakin.ru/en/for-doctors/cabinet/"><link rel="alternate" hreflang="x-default" href="https://matveyshemyakin.ru/for-doctors/cabinet/"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="https://matveyshemyakin.ru{path}"><meta property="og:type" content="website"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/mobile-fix.css"><link rel="stylesheet" href="/assets/free-learning/free-learning.css?v=20261102-1"><link rel="stylesheet" href="/assets/cabinet/cabinet.css?v=20261117-1"><script src="/analytics.js?v=20260811-2"></script>'''
    structured={'@context':'https://schema.org','@type':'CollectionPage','name':title,'description':desc,'inLanguage':lang,'url':'https://matveyshemyakin.ru'+path,'dateModified':'2026-11-17','mainEntity':{'@type':'ItemList','numberOfItems':len(resources),'itemListElement':[{'@type':'ListItem','position':i+1,'name':r.get(lang+'_name',r['name']),'url':('https://matveyshemyakin.ru'+prefix+r['url'] if r['url'].startswith('/') else r['url'])} for i,r in enumerate(resources)]}}
    head+='<script type="application/ld+json">'+json.dumps(structured,ensure_ascii=False)+'</script></head>'
    header='<header class="site-header" data-site-header="shared"></header>'
    sub='На каждый день · Для коллег · В подарок к 1000 подписчиков' if ru else 'For everyday practice · Curated for colleagues'
    lead='ОКТ, атласы, рекомендации и объяснения для пациентов — в одном рабочем пространстве. Выберите задачу и переходите к нужному инструменту.' if ru else 'OCT cases, atlases, guidelines and patient information in one workspace. Choose your task and open the tool you need.'
    art='''<svg viewBox="0 0 240 200" fill="none" aria-hidden="true"><rect x="15" y="18" width="210" height="138" rx="13" stroke="currentColor" stroke-width="3"/><path d="M85 184h70M120 156v28M16 133h208" stroke="currentColor" stroke-width="3"/><path d="M55 78c35-43 95-43 130 0-35 43-95 43-130 0Z" stroke="currentColor" stroke-width="3"/><circle cx="120" cy="78" r="23" stroke="currentColor" stroke-width="3"/><circle cx="120" cy="78" r="8" fill="currentColor"/></svg>'''
    main=f'''<body class="learn-page cabinet-page" data-learn-lang="{lang}"><a class="learn-skip" href="#learn-library">{'К ресурсам' if ru else 'Skip to resources'}</a>{header}<main id="content-material"><section class="learn-hero"><div class="container"><nav class="learn-breadcrumbs" aria-label="{'Навигационная цепочка' if ru else 'Breadcrumb'}"><a href="{prefix}/">{'Главная' if ru else 'Home'}</a><span>/</span><a href="{prefix}/for-doctors/">{'Для врачей' if ru else 'For doctors'}</a><span>/</span><span aria-current="page">{title}</span></nav><div class="learn-hero-grid"><div><p class="learn-eyebrow">{sub}</p><h1>{title}</h1><p class="learn-lead">{lead}</p><div class="learn-meta">{'Отобрал Матвей Шемякин · Обновлено 17 ноября 2026' if ru else 'Curated by Matvey Shemyakin · Updated 17 November 2026'}</div><div class="learn-hero-actions"><a class="learn-hero-btn" href="#learn-library">{'Открыть кабинет ↓' if ru else 'Open the desk ↓'}</a><button class="learn-share" type="button" id="learn-share">{'Отправить коллеге →' if ru else 'Share with a colleague →'}</button></div></div><div class="cabinet-art" aria-hidden="true">{art}<span>OCT · ATLAS · GUIDELINES</span></div></div><div class="learn-stats"><div><strong>13</strong><span>{'рабочих ресурсов' if ru else 'practical resources'}</span></div><div><strong>5</strong><span>{'задач приёма' if ru else 'clinical tasks'}</span></div><div><strong>RU / EN</strong><span>{'навигация на двух языках' if ru else 'bilingual navigation'}</span></div></div></div></section><section class="learn-content" id="learn-library"><div class="container"><p class="learn-kicker">{'Что нужно сейчас?' if ru else 'What do you need now?'}</p><h2>{'Выберите задачу приёма' if ru else 'Choose your clinical task'}</h2><p class="learn-intro">{'Русская навигация не меняет язык оригинала: у каждой карточки указан язык ресурса и условия доступа. Избранное сохраняется в этом браузере.' if ru else 'Navigation is bilingual; each card states the resource’s original language and access requirements. Bookmarks are stored in this browser.'}</p><div class="cabinet-tasks" aria-label="{'Быстрый выбор задачи' if ru else 'Quick task selection'}">'''
    for task,label in TASKS[lang].items(): main+=f'<button type="button" class="cabinet-task" data-task="{task}" aria-pressed="false">{label}</button>'
    main+='</div>'
    options=''.join(f'<option value="{k}">{v}</option>' for k,v in TASKS[lang].items())
    main+=f'''<div class="learn-toolbar" role="search"><label class="learn-search"><span class="learn-sr-only">{'Поиск по ресурсам' if ru else 'Search resources'}</span><input id="learn-query" type="search" autocomplete="off" placeholder="{'ОКТ, поля зрения, глаукома, памятка…' if ru else 'OCT, visual fields, glaucoma, patient handout…'}"></label><div class="learn-selects"><label><span class="learn-sr-only">{'Задача' if ru else 'Task'}</span><select id="learn-specialty"><option value="all">{'Все задачи' if ru else 'All tasks'}</option>{options}</select></label><label><span class="learn-sr-only">{'Условия доступа' if ru else 'Access requirements'}</span><select id="learn-format"><option value="all">{'Любой доступ' if ru else 'All access types'}</option><option value="open">{'Без регистрации' if ru else 'No registration'}</option><option value="register">{'Бесплатная регистрация' if ru else 'Free registration'}</option></select></label></div><div class="learn-tools-bottom"><label class="learn-fav-filter"><input id="learn-only-saved" type="checkbox">{'Только избранное' if ru else 'Bookmarks only'} <span id="learn-saved-count">0</span></label><button class="learn-reset" type="button" id="learn-reset">{'Сбросить ↺' if ru else 'Reset ↺'}</button></div></div><div class="learn-results" role="status" aria-live="polite">{'Найдено:' if ru else 'Resources:'} <strong id="learn-count">13</strong></div><div class="learn-grid" id="learn-grid">'''
    for i,r in enumerate(resources,1):
        name=r.get(lang+'_name',r['name']); description=r[lang+'_description']; tip=r[lang+'_tip'];url=prefix+r['url'] if r['url'].startswith('/') else r['url']; task=TASKS[lang][r['task']]
        access=('Бесплатно · нужна регистрация' if ru else 'Free · account required') if r['access']=='register' else ('Открытый доступ' if ru else 'Open access')
        search=' '.join([name,r['publisher'],description,r['ru_description'],r['en_description'],task, r['language']]).lower()
        main+=f'''<article class="learn-card" data-id="{r['id']}" data-specialties="{r['task']}" data-format="{r['access']}" data-search="{e(search,quote=True)}"><div class="learn-card-top"><span class="learn-card-index">{i:02d}</span><button class="learn-bookmark" type="button" data-bookmark="{r['id']}" aria-pressed="false" aria-label="{'В избранное' if ru else 'Save resource'}: {e(name)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3.5h12v17l-6-4.5-6 4.5z"/></svg></button></div><div class="learn-tag-row"><span class="learn-topic">{task}</span></div><h3>{e(name)}</h3><p class="cabinet-publisher">{e(r['publisher'])}</p><p class="learn-card-desc">{description}</p><div class="learn-info"><span class="learn-type">{r['language']}</span><span class="learn-access learn-access-{'register' if r['access']=='register' else 'open'}">{access}</span></div><p class="learn-tip">{tip}</p><a class="learn-open" href="{url}" {'target="_blank" rel="noopener noreferrer"' if not url.startswith('/') else ''} aria-label="{'Открыть' if ru else 'Open'}: {e(name)}">{'Открыть ресурс →' if ru else 'Open resource →'}</a><p class="cabinet-checked">{'Проверено' if ru else 'Checked'}: 17.11.2026</p></article>'''
    main+=f'''</div><p class="learn-empty" id="learn-empty" hidden>{'Ничего не найдено. Измените запрос или сбросьте фильтры.' if ru else 'No matches. Change your search or reset the filters.'}</p><section class="learn-note"><h2>{'Ещё пригодится' if ru else 'More for your practice'}</h2><p><a href="{prefix}/for-doctors/free-learning/">{'Бесплатное обучение: 21 международный ресурс →' if ru else 'Free learning: 21 international resources →'}</a></p><p class="learn-disclaimer">{'Материалы предназначены для медицинских специалистов. Атласы и учебные случаи помогают учиться и сопоставлять данные, но не устанавливают диагноз. Международные рекомендации применяйте с учётом локальных требований и клинической ситуации. Права на внешние материалы принадлежат их авторам; доступ и содержание могут меняться.' if ru else 'For healthcare professionals. Atlases and teaching cases support learning and comparison; they do not establish a diagnosis. Apply international guidelines in the context of local requirements and the clinical situation. External materials belong to their respective authors; access and content may change.'}</p></section></div></section></main>'''
    footer=re.search(r'<footer.*?</footer>',base,re.S).group()
    tail=re.search(r'<script defer src="/for-doctors/doctor-retention.js.*',base,re.S).group()
    doc=head+main+footer+'<script defer src="/assets/cabinet/cabinet.js?v=20261117-1"></script>'+tail
    out=ROOT/path.strip('/')/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(doc)
